#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <functional>
#include <unordered_map>
using namespace std;

priority_queue<long long> low;
priority_queue<long long, vector<long long>, greater<long long>> high;
unordered_map<long long, int> delayed;
long long lowSize = 0, highSize = 0;

void pruneLow() {
    while (!low.empty() && delayed[low.top()] > 0) {
        delayed[low.top()]--;
        low.pop();
    }
}

void pruneHigh() {
    while (!high.empty() && delayed[high.top()] > 0) {
        delayed[high.top()]--;
        high.pop();
    }
}

void balance() {
    if (lowSize > highSize + 1) {
        high.push(low.top());
        low.pop();
        lowSize--;
        highSize++;
        pruneLow();
    } else if (lowSize < highSize) {
        low.push(high.top());
        high.pop();
        lowSize++;
        highSize--;
        pruneHigh();
    }
}

void insertValue(long long x) {
    if (low.empty() || x <= low.top()) {
        low.push(x);
        lowSize++;
    } else {
        high.push(x);
        highSize++;
    }
    balance();
}

void eraseValue(long long x) {
    delayed[x]++;
    if (x <= low.top()) {
        lowSize--;
        if (x == low.top()) pruneLow();
    } else {
        highSize--;
        if (!high.empty() && x == high.top()) pruneHigh();
    }
    balance();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    for (long long i = 0; i < n; i++) {
        insertValue(a[i]);
        if (i >= k) eraseValue(a[i - k]);
        if (i >= k - 1) cout << low.top() << "\n";
    }

    return 0;
}

